import fs from 'node:fs';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
const baseline = JSON.parse(fs.readFileSync('docs/remediation/evidence/W08.01/baseline.json', 'utf8'));
const scripts = ['scripts/provision-stamp.sh', 'scripts/provision-staging.sh', 'scripts/setup.sh', 'scripts/deploy.sh'];
const active = s => s.split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#'));
for (const path of scripts) {
  const checked = spawnSync('/bin/bash', ['--noprofile', '--norc', '-n', path], { encoding: 'utf8', env: { PATH: '' } });
  assert.equal(checked.error, undefined); assert.equal(checked.status, 0, checked.stderr);
  if (path !== 'scripts/deploy.sh') {
    const lines = active(fs.readFileSync(path, 'utf8'));
    assert.equal(lines.length, 2, path);
    assert.match(lines[0], /^builtin printf '%s\\n'(?: '[^'\n]*')+ >&2$/);
    assert.equal(lines[1], 'exit 2');
    assert.match(lines[0], /W08/);
  }
}
const deploy = fs.readFileSync(scripts[3], 'utf8'), before = baseline.files.find(f => f.path === scripts[3]).content;
const logic = s => active(s).filter(l => !/^echo(?:\s|$)/.test(l));
assert.deepEqual(logic(deploy), logic(before), 'deploy execution logic changed');
const oldLines = new Set(before.split(/\r?\n/));
for (const line of deploy.split(/\r?\n/)) if (!oldLines.has(line) && /^\s*echo(?:\s|$)/.test(line)) {
  assert.match(line, /^\s*echo "[^"$`\\]*"\s*$/, 'changed diagnostics must be literal');
}
assert.doesNotMatch(deploy, /Run: bash scripts\/provision-|printf '\*:demo-site'|set AUTH_MODE.*open/);
const runbook = fs.readFileSync('docs/deployment/01-deploy.md', 'utf8');
assert.doesNotMatch(runbook, /Status:\*\* verified|## The one safe path|bash scripts\/provision-|printf '\*:demo-site'|open.*one-line.*rollback/);
assert.match(runbook, /W08/);
console.log('PASS: four scripts parse; three exact literal refusal bodies; deploy executable logic unchanged; operative recovery guidance retired. Source-only, no target script executed.');

