node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
const sha = data => createHash('sha256').update(data).digest('hex');
const read = path => JSON.parse(fs.readFileSync(path, 'utf8'));
const artifact = read('docs/remediation/evidence/W08.01/artifact.json');
const worker = read('docs/remediation/evidence/W08.01/worker.json');
const baseline = read('docs/remediation/evidence/W08.01/baseline.json');
const contract = read('docs/remediation/design/W08.01/task-contract-v1.json');
assert.equal(artifact.digest, sha(JSON.stringify({ contract_digest: artifact.contract_digest, configuration: artifact.configuration, files: artifact.files.map(({path,sha256,role}) => ({path,sha256,role})).sort((a,b)=>a.path.localeCompare(b.path)) })));
assert.equal(artifact.contract_digest, contract.preflight.contract_digest);
assert.equal(artifact.files.length,10);
for (const pin of artifact.files) assert.equal(sha(fs.readFileSync(pin.path)),pin.sha256,pin.path);
assert.equal(worker.implementation.files.length,5);
for (const final of worker.implementation.files) {
  const original = baseline.files.find(f=>f.path===final.path);
  const initial = worker.baseline.initial_files.find(f=>f.path===final.path);
  assert.equal(sha(original.content),original.sha256);
  assert.equal(initial.sha256,original.sha256);
  assert.equal(initial.bytes,Buffer.byteLength(original.content));
  const actual=fs.readFileSync(final.path);
  assert.equal(actual.toString('utf8'),final.content_utf8);
  assert.equal(actual.length,final.bytes);
  assert.equal(sha(actual),final.sha256);
  const diff=spawnSync('git',['diff','--',final.path],{encoding:'utf8'});
  assert.equal(diff.status,0); assert.equal(diff.stdout,final.admission_diff,final.path);
}
assert.equal(worker.checks[0].command,contract.checks[0].command);
assert.equal(worker.checks[0].exit_code,0);
assert.equal(worker.checks[1].exit_code,0);
assert.equal(worker.checks[1].output,'');
const scope=read('docs/remediation/evidence/W08.01/package-scope.json');
assert.deepEqual(scope.before.canonical,scope.after.canonical);
assert.equal(scope.after.scope_status,'open');
assert.equal(scope.after.decomposition.status,'partial');
console.log('PASS: 10 artifact pins and canonical manifest digest; five original/final byte/hash records and exact Git patches; worker K1 command/result and recorded scoped whitespace; canonical W08 retained open/partial. No target script or whitespace check executed.');
